/* Y2K — glossy chrome-blue, bubbly gradients, silver bevels, cyan glow */
.theme-y2k {
  --bg: oklch(0.9 0.05 230);
  --surface: oklch(0.97 0.02 230);
  --surface-2: oklch(0.86 0.06 225);
  --fg: oklch(0.22 0.06 265);
  --fg-muted: oklch(0.46 0.07 265);
  --accent: oklch(0.7 0.19 300);
  --accent-fg: oklch(0.99 0 0);
  --accent-2: oklch(0.82 0.14 200);
  --line: oklch(0.72 0.08 240);
  --success: oklch(0.78 0.17 155);
  --warning: oklch(0.86 0.16 92);
  --danger: oklch(0.66 0.22 18);

  --radius: 1.25rem;
  --radius-sm: 0.75rem;
  --radius-lg: 2rem;
  --radius-pill: 9999px;

  --shadow-1: inset 0 1px 0 oklch(1 0 0 / 90%), 0 2px 6px -1px oklch(0.4 0.1 250 / 45%);
  --shadow-2: inset 0 2px 0 oklch(1 0 0 / 95%), 0 10px 22px -8px oklch(0.4 0.12 250 / 55%);
  --shadow-3: inset 0 3px 0 oklch(1 0 0 / 95%), 0 22px 48px -14px oklch(0.4 0.12 250 / 60%);
  --glow: 0 0 26px -4px oklch(0.82 0.14 200 / 85%);

  --border-width: 2px;
  --blur-amount: 4px;

  --font-display: "Audiowide", sans-serif;
  --font-body: "Poppins", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: 0.02em;
  --label-transform: uppercase;
  --label-tracking: 0.16em;

  background-color: var(--bg);
  background-image:
    radial-gradient(40rem 24rem at 8% 0%, oklch(0.95 0.06 200 / 85%), transparent 60%),
    radial-gradient(38rem 26rem at 96% 14%, oklch(0.86 0.11 320 / 70%), transparent 62%),
    linear-gradient(180deg, oklch(0.95 0.04 230), oklch(0.82 0.07 245));
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-y2k h1,
.theme-y2k h2,
.theme-y2k h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  background-image: linear-gradient(180deg, oklch(0.99 0.01 240), oklch(0.62 0.14 265));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* signature */
.theme-y2k h1 { background: linear-gradient(180deg, #ffffff, var(--accent) 55%, var(--accent-2)); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 2px 0 oklch(0.3 0.1 300 / 60%)); }
.theme-y2k button { background-image: linear-gradient(180deg, oklch(1 0 0 / 45%), transparent 50%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
